ys-training/quickapp-microservices/git/trees/50e23b06c522304ac07a2819a58203965b270f34"},"url":"https://api.github.com/repos/infosys-training/quickapp-microservices/git/commits/db7de3656344bf3b1a823e4b3422789d6eb7c942","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/in/811515?v=4","events_url":"https://api.github.com/users/devin-ai-integration%5Bbot%5D/events{/privacy}","followers_url":"https://api.github.com/users/devin-ai-integration%5Bbot%5D/followers","following_url":"https://api.github.com/users/devin-ai-integration%5Bbot%5D/following{/other_user}","gists_url":"https://api.github.com/users/devin-ai-integration%5Bbot%5D/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/apps/devin-ai-integration","id":158243242,"login":"devin-ai-integration[bot]","node_id":"BOT_kgDOCW6Zqg","organizations_url":"https://api.github.com/users/devin-ai-integration%5Bbot%5D/orgs","received_events_url":"https://api.github.com/users/devin-ai-integration%5Bbot%5D/received_events","repos_url":"https://api.github.com/users/devin-ai-integration%5Bbot%5D/repos","site_admin":false,"starred_url":"https://api.github.com/users/devin-ai-integration%5Bbot%5D/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/devin-ai-integration%5Bbot%5D/subscriptions","type":"Bot","url":"https://api.github.com/users/devin-ai-integration%5Bbot%5D","user_view_type":"public"},"html_url":"https://github.com/infosys-training/quickapp-microservices/commit/db7de3656344bf3b1a823e4b3422789d6eb7c942","node_id":"C_kwDOSnjFptoAKGRiN2RlMzY1NjM0NGJmM2IxYTgyM2U0YjM0MjI3ODlkNmViN2M5NDI","parents":[],"sha":"db7de3656344bf3b1a823e4b3422789d6eb7c942","url":"https://api.github.com/repos/infosys-training/quickapp-microservices/commits/db7de3656344bf3b1a823e4b3422789d6eb7c942"}],"requestUrl":"https://api.github.com/repos/infosys-training/quickapp-microservices/commits?per_page=1